"""Add the user's supplied professor review, preserving its original choice order."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];p=R/'data.json';d=json.loads(p.read_text(encoding='utf-8'))
d['questions']=[q for q in d['questions'] if q.get('practiceSet')!='chem-professor']
def q(n,ch,title,body,choices,answer,why,figure=None,alt=None):
 x=dict(id=f'PE2-{n:02}',review='chem-6-8',section=f'CHEM {ch}',title=title,body=body if isinstance(body,list) else [body],choices=choices,correctChoices=[answer],multiple=False,kind='mcq',conceptual=False,practiceSet='chem-professor',sourceLabel='Professor review',sourceDocument='Exam 2 Review-3.pdf',sourceQuestion=n,family=f'F{n:02}',familyTitle=next(f['title'] for f in d['chemistryExam2']['families'] if f['professorQuestion']==n),choiceVersion='professor-exam2-v1',answer={'blocks':[chr(65+answer)+'. '+choices[answer],'Why: '+why]})
 if figure:x.update(figure='figures/chem-exam2/prof-q'+figure+'.png',figureAlt=alt)
 d['questions'].append(x)
q(1,6,'Potassium photoelectric threshold',['Data from the review sheet: h=6.63 × 10⁻³⁴ J·s; c=3.00 × 10⁸ m/s.','The binding energy for potassium is 3.68 × 10⁻¹⁹ J. Which is the longest wavelength which could eject an electron from the potassium surface?'],['520 nm','540 nm','450 nm','480 nm'],1,'hc/Ebinding ≈ 540 nm; longer wavelengths carry insufficient photon energy.')
q(2,6,'Shortest-wavelength hydrogen emission','Which electronic transition in a hydrogen atom corresponds to emission of the shortest-wavelength photon?',['n=6 → n=7','n=4 → n=3','n=3 → n=2','n=3 → n=1'],3,'The 3 → 1 transition has the largest downward energy gap of those listed.')
q(3,6,'Allowed quantum-number combinations','Which combination of quantum numbers is not allowed?',['n=3, ℓ=0, mℓ=0, mₛ=−½','n=1, ℓ=1, mℓ=0, mₛ=−½','n=2, ℓ=1, mℓ=−1, mₛ=+½','n=4, ℓ=3, mℓ=−2, mₛ=−½'],1,'For n=1, only ℓ=0 is allowed.')
q(4,6,'An occupied magnetic quantum number','How many electrons in a ground-state argon atom can have mℓ=+1?',['2','4','8','10'],1,'The filled 2p and 3p subshells each contribute two; s orbitals have mℓ=0.')
q(5,6,'Increasing-radius series','Which series is correctly arranged in increasing radius?',['Ca²⁺ < K⁺ < Ar < Cl⁻ < S²⁻','Cl⁻ < Ar < S²⁻ < K⁺ < Ca²⁺','K⁺ < S²⁻ < Ca²⁺ < Ar < Cl⁻','S²⁻ < Ca²⁺ < Ar < K⁺ < Cl⁻','Ca²⁺ < K⁺ < Cl⁻ < S²⁻ < Ar'],0,'All five species have 18 electrons; increasing nuclear charge gives decreasing size in this isoelectronic comparison.')
q(6,6,'Silicon’s ionization-energy jump','A large jump in silicon’s successive ionization energies occurs between which two values?',['IE₂ and IE₃','IE₅ and IE₆','IE₃ and IE₄','IE₄ and IE₅'],3,'Si has four valence electrons; the fifth removal reaches a core electron.')
q(7,6,'Choose a paramagnetic ion','Which ion is paramagnetic? Use isolated ground-state ions and Hund’s-rule d occupancy.',['Al³⁺','Zn²⁺','Ti⁴⁺','Co²⁺'],3,'Co²⁺ is [Ar]3d⁷ with unpaired electrons; the other ions listed are closed shell.')
q(8,6,'Which pair has different configurations?','Which pair does not have identical ground-state electron configurations?',['Ne and Mg²⁺','Ni and Cu⁺','K⁺ and S²⁻','O²⁻ and F⁻'],1,'Ni is [Ar]3d⁸4s²; Cu⁺ is [Ar]3d¹⁰. Their electron counts match but their configurations differ.')
q(9,7,'Best COCl₂ Lewis structure','Select the best Lewis structure for COCl₂ from the four panels.',['Panel A','Panel B','Panel C','Panel D'],3,'D has 24 valence electrons, octets on C/O/Cl, and zero formal charges. In the supplied diagram B is missing an O lone pair.','09','Four COCl₂ Lewis-structure options A-D, reproduced from the supplied question; lone-pair dots are essential.')
q(10,7,'Formula and charge from a Lewis drawing','What is the formula for the following Lewis structure?',['CNO²⁻','CNO⁻','CNO','CNO⁺'],1,'The displayed O≡C–N structure has 16 electrons, one more than the neutral valence sum of 15.','10','O≡C–N with one O lone pair and three N lone pairs.')
q(11,7,'Formal charge on nitrogen','The formal charge on N in a major octet Lewis structure of NO₂⁻ is:',['−1','0','+1','+2'],1,'N has one lone pair and total bond order 3: 5−2−3=0.')
q(12,7,'Carbonate resonance forms','Carbonate ion, CO₃²⁻, has how many equivalent major resonance forms?',['1','2','3','None of these'],2,'The C=O bond can be placed at any of three equivalent O sites.')
q(13,7,'Shape of a mixed-ligand chlorine center','What is the molecular shape of ClO₃F as predicted by VSEPR theory for the displayed structure?',['Trigonal pyramidal','Square planar','Square pyramidal','Tetrahedral'],3,'Four bonded neighbors and no central lone pair give AX₄; multiple bonds count as one domain each.','13','Supplied ClO₃F Lewis drawing with Cl bonded to three O atoms and one F atom.')
q(14,7,'Angle in PH₂⁻','What is the H–P–H bond angle in PH₂⁻, according to the lecture VSEPR model?',['Less than 109.5°','109.5°','120°','180°'],0,'Two bonds and two lone pairs give tetrahedral electron geometry and a bent shape with compressed bond angle.')
q(15,7,'Hybridization in SnCl₃⁻','Valence bond theory predicts that tin uses which hybrid orbitals in SnCl₃⁻?',['sp','sp²','sp³','sp³d'],2,'Three bonds plus one central lone pair give four domains and the sp³ lecture-model label.')
q(16,7,'Right-most carbon hybridization','Which hybridization describes the right-most carbon atom in the molecule below?',['sp','sp²','sp³','sp³d'],0,'The nitrile carbon has two σ-domain directions; the triple bond’s π components do not add domains.','16','The supplied structure is CH₃–C(=O)–CH₂–C≡N; the right-most carbon is the nitrile carbon.')
q(17,7,'Decreasing electronegativity','Arrange fluorine, silicon, sulfur, and barium in decreasing electronegativity.',['F > Si > S > Ba','S > Si > F > Ba','F > S > Si > Ba','Si > F > Ba > S'],2,'F is highest; S lies to the right of Si, and Ba is a low-electronegativity metal.')
q(18,8,'Zero molecular dipole','Which molecule has a zero dipole moment?',['NF₃','IF₃','BF₃','PF₃'],2,'BF₃ is symmetric trigonal planar; its three B–F bond dipoles cancel.')
q(19,8,'CH₂Cl₂: shape and polarity','CH₂Cl₂ is a ______ molecule and its molecular shape is ______.',['Polar; seesaw','Polar; tetrahedral','Nonpolar; square planar','Nonpolar; tetrahedral'],1,'Four electron domains give tetrahedral geometry; the mixed H/Cl ligands prevent cancellation.')
q(20,7,'Sigma and pi bonds in phenol','There are how many σ and π bonds, respectively, in the phenol molecule?',['13, 3','3, 4','4, 3','10, 3'],0,'Six ring σ + five C–H + C–O + O–H = 13 σ; the three ring double bonds add 3 π.','20','The supplied phenol drawing shows six ring carbons, five ring hydrogens, and an O–H substituent.')
q(21,8,'Normal boiling point from vapor-pressure data','A liquid has ΔHvap=17.2 kJ/mol. At 285 K its vapor pressure is 212 torr. What is its normal boiling point? R=8.314 J·mol⁻¹·K⁻¹.',['73°C','95°C','346°C','46°C'],0,'The two-point Clausius–Clapeyron relation gives about 346 K, or 73°C.')
q(22,8,'Highest boiling point among the listed substances','Which compound has the highest boiling point?',['SO₂','CO₂','O₂','N₂'],0,'SO₂ has the strongest combined attractions among these choices. At 1 atm CO₂ sublimes rather than having a normal liquid boiling point.')
q(23,8,'Lowest vapor pressure','Which compound has the lowest equilibrium vapor pressure? Compare at the same temperature.',['C₂H₆','CH₃OH','CH₃Cl','CH₄'],1,'Methanol’s self-hydrogen bonding strongly reduces escape to the vapor relative to these other small molecules.')
q(24,8,'Identify the sample without self-hydrogen bonding','Which compound does not exhibit conventional hydrogen bonding between identical molecules?',['NH₃','CH₃OH','HF','CF₄'],3,'CF₄ lacks a hydrogen bonded to N, O, or F; the other three have appropriate donor H atoms.')
assert len([q for q in d['questions'] if q.get('practiceSet')=='chem-professor'])==24
d['chemistryExam2'].update(total=120,professor=24)
for g in d['guides']:
 if g.get('review')=='chem-6-8' and g.get('title')=='How to use this review':
  g['body'][0]='The bank contains 120 MCQs: 72 new questions in 24 three-variant families, 24 curated and converted lecture-coverage questions, and all 24 questions from your supplied professor review. Original professor choices retain their original letter order. Minor wording/notation clarifications and supplied constants do not change the intended questions.'
  g['body'].append('Professor review labels identify the supplied questions. Turn off Show source labels for neutral question numbering and mixed practice. Original figure extracts retain their printed electron dots; in professor question 9 the correct panel is D, since B omits an oxygen lone pair.') if not any('Show source labels' in t for t in g['body']) else None
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Added 24 labeled professor-review questions; chemistry total is now 120.')
